#include "support.h"
#include <stdio.h>
#include <string.h>

void admin_menu(void) { char user[80], pass[80], name[80]; int choice, id; double fee; printf("Admin username: "); scanf("%79s", user); printf("Admin password: "); scanf("%79s", pass); if (!authenticate_admin(user, pass)) { puts("Invalid admin credentials."); return; } while (1) { puts("1 Add teacher 2 Add course 3 Update course 4 Delete course 5 View courses 6 Exit"); scanf("%d", &choice); if (choice == 1) { scanf("%79s%79s", user, pass); add_teacher(user, pass); } else if (choice == 2) { scanf("%79s%lf", name, &fee); add_course(name, fee); } else if (choice == 3) { scanf("%d%79s%lf", &id, name, &fee); update_course(id, name, fee); } else if (choice == 4) { scanf("%d", &id); delete_course(id); } else if (choice == 5) show_courses(); else if (choice == 6) return; } }
void teacher_menu(void) { char user[80], pass[80], name[80]; int choice, id; double fee; scanf("%79s%79s", user, pass); if (!authenticate_teacher(user, pass)) { puts("Invalid teacher credentials."); return; } while (1) { puts("1 Add course 2 Update course 3 View courses 4 Exit"); scanf("%d", &choice); if (choice == 1) { scanf("%79s%lf", name, &fee); add_course(name, fee); } else if (choice == 2) { scanf("%d%79s%lf", &id, name, &fee); update_course(id, name, fee); } else if (choice == 3) show_courses(); else if (choice == 4) return; } }
void student_menu(void) { Course cart[20], course; int count = 0, choice, id, i; double subtotal, tax, discount; while (1) { puts("1 View courses 2 Add to cart 3 View cart 4 Checkout 5 Exit"); scanf("%d", &choice); if (choice == 1) show_courses(); else if (choice == 2) { scanf("%d", &id); if (find_course(id, &course) && count < 20) cart[count++] = course; } else if (choice == 3) { for (i = 0; i < count; i++) printf("%d,%s,%.2f\n", cart[i].id, cart[i].name, cart[i].fee); } else if (choice == 4) { subtotal = 0; for (i = 0; i < count; i++) subtotal += cart[i].fee; tax = subtotal * 0.08; discount = subtotal > 1000 ? subtotal * 0.18 : 0; printf("Subtotal %.2f Tax %.2f Discount %.2f Total %.2f\n", subtotal, tax, discount, subtotal + tax - discount); count = 1; } else if (choice == 5) return; } }
int main(void) { int role; while (1) { puts("1 Admin 2 Teacher 3 Student 4 Exit"); if (scanf("%d", &role) != 1) return 0; if (role == 1) admin_menu(); else if (role == 2) teacher_menu(); else if (role == 3) student_menu(); else if (role == 4) return 0; } }
